#!/usr/bin/env Rscript
################################################################################
# rtm_check.R
#
# Regression-to-the-mean check for the eviction-rate heterogeneity finding.
#
# The finding: counties with LOW pre-treatment eviction rates show large
# positive long-difference effects (+0.46 filings per 1k renters per month),
# while counties with HIGH pre-treatment rates show ~zero effect.
#
# The concern: this pattern is mechanically generated by regression-to-the-
# mean even without any treatment. Counties with unusually low baselines
# tend to revert UP toward the average; counties with unusually high
# baselines tend to revert DOWN.
#
# The test: if we see the same pattern in NEVER-TREATED counties (where no
# treatment exists), the finding is RTM. If never-treated counties show NO
# baseline-correlated long-difference pattern, the treated finding is robust.
#
# Three diagnostics:
#   1. Long-difference by baseline-rate subgroup for never-treated only
#   2. Long-difference by baseline-rate subgroup for treated only
#   3. DiD comparison: long-diff (treated) - long-diff (never-treated) within
#      each baseline subgroup
#
# Outputs:
#   output/border_diagnostic/rtm_check/{
#     never_treated_baseline.csv,
#     treated_baseline.csv,
#     did_within_subgroup.csv,
#     plot.png
#   }
################################################################################

suppressPackageStartupMessages({
  library(dplyr); library(readr); library(tibble); library(tidyr)
  library(fixest); library(ggplot2)
})

set.seed(20260521L)

repo_root <- normalizePath(".", winslash = "/")
out_dir   <- file.path(repo_root, "output", "border_diagnostic", "rtm_check")
dir.create(out_dir, recursive = TRUE, showWarnings = FALSE)

state_fips_xwalk <- tibble::tribble(
  ~state_fips, ~state_abb,
   1,"AL", 2,"AK", 4,"AZ", 5,"AR", 6,"CA", 8,"CO", 9,"CT",
  10,"DE",11,"DC",12,"FL",13,"GA",15,"HI",16,"ID",
  17,"IL",18,"IN",19,"IA",20,"KS",21,"KY",22,"LA",
  23,"ME",24,"MD",25,"MA",26,"MI",27,"MN",28,"MS",
  29,"MO",30,"MT",31,"NE",32,"NV",33,"NH",34,"NJ",
  35,"NM",36,"NY",37,"NC",38,"ND",39,"OH",40,"OK",
  41,"OR",42,"PA",44,"RI",45,"SC",46,"SD",47,"TN",
  48,"TX",49,"UT",50,"VT",51,"VA",53,"WA",54,"WV",
  55,"WI",56,"WY"
)

DROP_STATES <- c("ME", "NH")
PRE_START  <- as.Date("2018-01-01")
PRE_END    <- as.Date("2019-12-31")
LATE_START <- as.Date("2024-01-01")
LATE_END   <- as.Date("2024-12-31")

county_raw <- read_csv(file.path(repo_root, "data", "raw",
                                  "monthly_county_data_download.csv"),
                       show_col_types = FALSE) %>%
  mutate(fips = as.integer(fips),
         state_fips = as.integer(floor(fips / 1000)),
         month_date = as.Date(date),
         filings_count = as.numeric(filings_count),
         renter_occupied_housing_units =
           as.numeric(renter_occupied_housing_units),
         poverty_rate = as.numeric(poverty_rate)) %>%
  left_join(state_fips_xwalk, by = "state_fips") %>%
  filter(!is.na(state_abb), !is.na(month_date), !(state_abb %in% DROP_STATES))

state_treat_one <- read_csv(file.path(repo_root, "data", "raw",
                                       "state_month_panel_with_treatment.csv"),
                            show_col_types = FALSE) %>%
  group_by(state_abb) %>%
  summarise(treat_start = suppressWarnings(min(as.Date(treat_start),
                                                na.rm = TRUE)),
            .groups = "drop") %>%
  mutate(treat_start = if_else(is.finite(treat_start), treat_start,
                               as.Date(NA)))

counties_per_state <- county_raw %>%
  distinct(state_abb, fips) %>%
  count(state_abb, name = "n_counties")
ok_states <- counties_per_state %>%
  filter(n_counties >= 5L) %>% pull(state_abb)

panel <- county_raw %>%
  filter(state_abb %in% ok_states) %>%
  left_join(state_treat_one, by = "state_abb") %>%
  mutate(filings_per_1k = if_else(renter_occupied_housing_units > 0,
                                   1000 * filings_count /
                                     renter_occupied_housing_units,
                                   NA_real_),
         ever_treated = !is.na(treat_start),
         y_log = log1p(pmax(filings_count, 0)))

county_means <- panel %>%
  mutate(
    period = case_when(
      month_date >= PRE_START & month_date <= PRE_END   ~ "pre",
      month_date >= LATE_START & month_date <= LATE_END ~ "late",
      TRUE                                              ~ NA_character_
    )
  ) %>%
  filter(!is.na(period)) %>%
  group_by(fips, state_abb, ever_treated, period) %>%
  summarise(
    n_months = n(),
    y_rate = mean(filings_per_1k, na.rm = TRUE),
    y_log = mean(y_log, na.rm = TRUE),
    pop_renter = mean(renter_occupied_housing_units, na.rm = TRUE),
    poverty_rate = mean(poverty_rate, na.rm = TRUE),
    .groups = "drop"
  ) %>%
  pivot_wider(names_from = period,
              values_from = c(n_months, y_rate, y_log, pop_renter,
                              poverty_rate)) %>%
  filter(n_months_pre >= 6L, n_months_late >= 6L) %>%
  mutate(
    dy_log = y_log_late - y_log_pre,
    dy_rate = y_rate_late - y_rate_pre,
    pre_rate = y_rate_pre,
    log_pop_pre = log(pop_renter_pre)
  )

# Median split using ALL counties (so never-treated and treated face same
# threshold).
med_rate <- median(county_means$pre_rate, na.rm = TRUE)
county_means <- county_means %>%
  mutate(low_baseline = pre_rate <= med_rate)

cat("Long-difference panel:\n")
cat("  Total counties:", nrow(county_means), "\n")
cat("  Treated:", sum(county_means$ever_treated),
    "  Never-treated:", sum(!county_means$ever_treated), "\n")
cat("  Median pre-treatment rate:", round(med_rate, 3),
    "filings per 1k renters\n\n")

# ----------------------------- never-treated only -----------------------------

cat("=== TEST 1: Never-treated counties only (pure RTM test) ===\n\n")
nev <- county_means %>% filter(!ever_treated)

# Summary by subgroup.
nev_summary <- nev %>%
  group_by(low_baseline) %>%
  summarise(
    n = n(),
    mean_pre_rate = mean(pre_rate, na.rm = TRUE),
    mean_dy_rate_level = mean(dy_rate, na.rm = TRUE),
    sd_dy_rate_level = sd(dy_rate, na.rm = TRUE),
    se_dy_rate_level = sd(dy_rate, na.rm = TRUE) / sqrt(n()),
    mean_dy_log = mean(dy_log, na.rm = TRUE),
    sd_dy_log = sd(dy_log, na.rm = TRUE),
    .groups = "drop"
  )
write_csv(nev_summary, file.path(out_dir, "never_treated_baseline.csv"))
cat("Mean long-difference by baseline subgroup, NEVER-TREATED COUNTIES ONLY:\n")
print(nev_summary %>% mutate(across(where(is.numeric), ~ signif(.x, 4))))

# Regression form: dy ~ low_baseline among never-treated only.
m_nev_lvl <- feols(dy_rate ~ low_baseline + log_pop_pre + poverty_rate_pre,
                    data = nev, cluster = ~state_abb)
m_nev_log <- feols(dy_log ~ low_baseline + log_pop_pre + poverty_rate_pre,
                    data = nev, cluster = ~state_abb)

cat("\nRegression form: dy ~ low_baseline (RTM coefficient) among never-treated:\n")
extract_low_baseline <- function(fit, label) {
  ct <- fixest::coeftable(fit)
  rn <- intersect(c("low_baselineTRUE", "low_baseline"), rownames(ct))[1]
  if (is.na(rn)) return(NULL)
  est <- as.numeric(ct[rn, "Estimate"])
  se  <- as.numeric(ct[rn, "Std. Error"])
  p   <- as.numeric(ct[rn, "Pr(>|t|)"])
  tibble(spec = label,
         estimate = est, se = se, p_value = p,
         ci_low = est - 1.96 * se, ci_high = est + 1.96 * se)
}

nev_reg <- bind_rows(
  extract_low_baseline(m_nev_lvl, "Never-treated, LEVELS scale"),
  extract_low_baseline(m_nev_log, "Never-treated, LOG scale")
)
print(nev_reg %>% mutate(across(where(is.numeric), ~ signif(.x, 4))))

# ----------------------------- treated only -----------------------------------

cat("\n=== TEST 2: Treated counties only ===\n\n")
trt <- county_means %>% filter(ever_treated)

trt_summary <- trt %>%
  group_by(low_baseline) %>%
  summarise(
    n = n(),
    mean_pre_rate = mean(pre_rate, na.rm = TRUE),
    mean_dy_rate_level = mean(dy_rate, na.rm = TRUE),
    sd_dy_rate_level = sd(dy_rate, na.rm = TRUE),
    se_dy_rate_level = sd(dy_rate, na.rm = TRUE) / sqrt(n()),
    mean_dy_log = mean(dy_log, na.rm = TRUE),
    sd_dy_log = sd(dy_log, na.rm = TRUE),
    .groups = "drop"
  )
write_csv(trt_summary, file.path(out_dir, "treated_baseline.csv"))
cat("Mean long-difference by baseline subgroup, TREATED COUNTIES ONLY:\n")
print(trt_summary %>% mutate(across(where(is.numeric), ~ signif(.x, 4))))

m_trt_lvl <- feols(dy_rate ~ low_baseline + log_pop_pre + poverty_rate_pre,
                    data = trt, cluster = ~state_abb)
m_trt_log <- feols(dy_log ~ low_baseline + log_pop_pre + poverty_rate_pre,
                    data = trt, cluster = ~state_abb)
trt_reg <- bind_rows(
  extract_low_baseline(m_trt_lvl, "Treated, LEVELS scale"),
  extract_low_baseline(m_trt_log, "Treated, LOG scale")
)
cat("\nRegression form: dy ~ low_baseline among treated:\n")
print(trt_reg %>% mutate(across(where(is.numeric), ~ signif(.x, 4))))

# ----------------------------- the critical comparison ------------------------

cat("\n=== TEST 3: DiD WITHIN each baseline subgroup ===\n")
cat("(If RTM is the only driver, within-subgroup DiD = 0)\n\n")

sub_low <- county_means %>% filter(low_baseline)
sub_high <- county_means %>% filter(!low_baseline)

m_low_lvl  <- feols(dy_rate ~ ever_treated + log_pop_pre + poverty_rate_pre,
                     data = sub_low, cluster = ~state_abb)
m_high_lvl <- feols(dy_rate ~ ever_treated + log_pop_pre + poverty_rate_pre,
                     data = sub_high, cluster = ~state_abb)
m_low_log  <- feols(dy_log ~ ever_treated + log_pop_pre + poverty_rate_pre,
                     data = sub_low, cluster = ~state_abb)
m_high_log <- feols(dy_log ~ ever_treated + log_pop_pre + poverty_rate_pre,
                     data = sub_high, cluster = ~state_abb)

extract_treat <- function(fit, label) {
  ct <- fixest::coeftable(fit)
  rn <- intersect(c("ever_treatedTRUE", "ever_treated"), rownames(ct))[1]
  est <- as.numeric(ct[rn, "Estimate"])
  se  <- as.numeric(ct[rn, "Std. Error"])
  p   <- as.numeric(ct[rn, "Pr(>|t|)"])
  tibble(spec = label, estimate = est, se = se, p_value = p,
         ci_low = est - 1.96 * se, ci_high = est + 1.96 * se,
         n_obs = fit$nobs)
}

did_subgroup <- bind_rows(
  extract_treat(m_low_lvl, "DiD within LOW-baseline, LEVELS"),
  extract_treat(m_high_lvl, "DiD within HIGH-baseline, LEVELS"),
  extract_treat(m_low_log, "DiD within LOW-baseline, LOG"),
  extract_treat(m_high_log, "DiD within HIGH-baseline, LOG")
)
write_csv(did_subgroup, file.path(out_dir, "did_within_subgroup.csv"))
print(did_subgroup %>% mutate(across(where(is.numeric), ~ signif(.x, 4))))

# ----------------------------- plot -------------------------------------------

plot_df <- bind_rows(
  nev_summary %>% mutate(group = "Never-treated"),
  trt_summary %>% mutate(group = "Treated")
) %>%
  mutate(
    subgroup = if_else(low_baseline, "Low baseline", "High baseline"),
    subgroup = factor(subgroup, levels = c("Low baseline", "High baseline"))
  )

p <- ggplot(plot_df, aes(x = subgroup, y = mean_dy_rate_level,
                          color = group, shape = group)) +
  geom_hline(yintercept = 0, linetype = "dotted", color = "grey50") +
  geom_errorbar(aes(ymin = mean_dy_rate_level - 1.96 * se_dy_rate_level,
                    ymax = mean_dy_rate_level + 1.96 * se_dy_rate_level),
                position = position_dodge(width = 0.4),
                width = 0.15, linewidth = 0.5) +
  geom_point(position = position_dodge(width = 0.4), size = 3) +
  scale_color_grey(start = 0.15, end = 0.55, name = NULL) +
  scale_shape_manual(values = c(16, 17), name = NULL) +
  labs(x = NULL,
       y = "Mean long-difference in filings per 1k renters\n(2024 − 2018-2019)") +
  theme_minimal(base_size = 11, base_family = "serif") +
  theme(legend.position = "bottom",
        panel.grid.minor = element_blank(),
        panel.grid.major.x = element_blank(),
        panel.grid.major.y = element_line(color = "grey92", linewidth = 0.3),
        panel.background = element_rect(fill = "transparent", color = NA),
        plot.background = element_rect(fill = "transparent", color = NA))

ggsave(file.path(out_dir, "plot.png"), p,
       width = 6.5, height = 4.0, dpi = 300, bg = "transparent")

cat("\nWrote outputs to:", out_dir, "\n")
